     1→// 桐城自摸麻将 - 局域网服务器
     2→// 运行方式: node majiang-server.js
     3→
     4→const http = require('http');
     5→const fs = require('fs');
     6→const path = require('path');
     7→const WebSocket = require('ws');
     8→
     9→const PORT = 8082;
    10→
    11→// ==================== HTTP服务器 ====================
    12→const server = http.createServer((req, res) => {
    13→    console.log(`HTTP请求: ${req.url}`);
    14→
    15→    if (req.url === '/' || req.url === '/index.html') {
    16→        const htmlPath = path.join(__dirname, 'majiang-lan.html');
    17→        fs.readFile(htmlPath, (err, data) => {
    18→            if (err) {
    19→                res.writeHead(404);
    20→                res.end('游戏文件未找到');
    21→                return;
    22→            }
    23→            res.writeHead(200, {
    24→                'Content-Type': 'text/html; charset=utf-8'
    25→            });
    26→            res.end(data);
    27→        });
    28→    } else if (req.url === '/favicon.ico') {
    29→        res.writeHead(204);
    30→        res.end();
    31→    } else {
    32→        res.writeHead(404);
    33→        res.end('Not Found');
    34→    }
    35→});
    36→
    37→// ==================== WebSocket服务器 ====================
    38→const wss = new WebSocket.Server({ server });
    39→
    40→// 游戏房间管理
    41→const tables = new Map();
    42→const playerToTable = new Map();
    43→let tableCounter = 0;
    44→
    45→// 所有已登录的客户端（用于广播牌桌列表）
    46→const loggedInClients = new Set();
    47→
    48→// ==================== 牌面常量 ====================
    49→const SUITS = ['筒', '条', '万'];
    50→const RANKS = [1, 2, 3, 4, 5, 6, 7, 8, 9];
    51→const WINDS = ['东', '南', '西', '北'];
    52→const ARROWS = ['中', '发', '白'];
    53→
    54→// 创建一副麻将牌
    55→function createDeck() {
    56→    const deck = [];
    57→
    58→    // 筒条万 (每种4张)
    59→    for (const suit of SUITS) {
    60→        for (const rank of RANKS) {
    61→            for (let i = 0; i < 4; i++) {
    62→                deck.push({
    63→                    suit,
    64→                    rank,
    65→                    type: 'number',
    66→                    id: `${suit}${rank}_${i}`
    67→                });
    68→            }
    69→        }
    70→    }
    71→
    72→    // 风牌 (每种4张)
    73→    for (const wind of WINDS) {
    74→        for (let i = 0; i < 4; i++) {
    75→            deck.push({
    76→                suit: '风',
    77→                rank: wind,
    78→                type: 'wind',
    79→                id: `风${wind}_${i}`
    80→            });
    81→        }
    82→    }
    83→
    84→    // 箭牌 (每种4张)
    85→    for (const arrow of ARROWS) {
    86→        for (let i = 0; i < 4; i++) {
    87→            deck.push({
    88→                suit: '箭',
    89→                rank: arrow,
    90→                type: 'arrow',
    91→                id: `箭${arrow}_${i}`
    92→            });
    93→        }
    94→    }
    95→
    96→    return deck; // 136张
    97→}
    98→
    99→// 洗牌
   100→function shuffle(deck) {
   101→    const shuffled = [...deck];
   102→    for (let i = shuffled.length - 1; i > 0; i--) {
   103→        const j = Math.floor(Math.random() * (i + 1));
   104→        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
   105→    }
   106→    return shuffled;
   107→}
   108→
   109→// 牌的显示名称
   110→function cardName(card) {
   111→    if (card.type === 'number') {
   112→        return `${card.rank}${card.suit}`;
   113→    } else {
   114→        return card.rank;
   115→    }
   116→}
   117→
   118→// ==================== 牌桌类 ====================
   119→class GameTable {
   120→    constructor(id, tableNumber) {
   121→        this.id = id;
   122→        this.tableNumber = tableNumber;
   123→        this.players = new Map(); // playerId -> player info
   124→        this.spectators = new Map();
   125→        this.maxPlayers = 4;
   126→        this.gameTimer = null; // 游戏计时器
   127→        this.lastSeatShuffleTime = Date.now(); // 上次换座位时间
   128→        this.sessionStartTime = Date.now(); // 会话开始时间
   129→
   130→        this.gameState = {
   131→            started: false,
   132→            currentPlayer: 0, // 0-3, 当前出牌玩家索引
   133→            dealer: 0, // 庄家索引
   134→            deck: [], // 牌堆
   135→            hands: {}, // playerId -> cards[]
   136→            wildCard: null, // 万能牌
   137→            discardedPile: [], // 打出的牌
   138→            showedCards: {}, // playerId -> { fa: [], gang: [] }
   139→            faUsed: {}, // playerId -> 玩家是否已换过发
   140→            lastDrawn: null, // 最后摸的牌
   141→            gameStartTime: null, // 游戏开始时间
   142→            totalGameTime: 0 // 游戏总时长（秒）
   143→        };
   144→    }
   145→
   146→    // 获取按座位排序的玩家ID数组
   147→    getSortedPlayerIds() {
   148→        return Array.from(this.players.entries())
   149→            .sort((a, b) => a[1].seatNum - b[1].seatNum)
   150→            .map(([id]) => id);
   151→    }
   152→
   153→    // 添加玩家
   154→    addPlayer(ws, playerId, playerName, seatNum = null) {
   155→        if (this.players.size >= this.maxPlayers) return false;
   156→        if (this.gameState.started) return false;
   157→
   158→        let actualSeat;
   159→        if (seatNum !== null && seatNum >= 1 && seatNum <= 4) {
   160→            const occupied = Array.from(this.players.values()).some(p => p.seatNum === seatNum);
   161→            if (occupied) return false;
   162→            actualSeat = seatNum;
   163→        } else {
   164→            const occupiedSeats = new Set(Array.from(this.players.values()).map(p => p.seatNum));
   165→            for (let i = 1; i <= 4; i++) {
   166→                if (!occupiedSeats.has(i)) {
   167→                    actualSeat = i;
   168→                    break;
   169→                }
   170→            }
   171→        }
   172→
   173→        this.players.set(playerId, {
   174→            ws,
   175→            id: playerId,
   176→            name: playerName,
   177→            seatNum: actualSeat,
   178→            ready: false,
   179→            isAI: false
   180→        });
   181→
   182→        return true;
   183→    }
   184→
   185→    // 移除玩家
   186→    removePlayer(playerId) {
   187→        this.players.delete(playerId);
   188→        return this.players.size === 0;
   189→    }
   190→
   191→    // 检查是否所有玩家都已断开连接
   192→    isAllPlayersDisconnected() {
   193→        if (this.players.size === 0) return true;
   194→        for (const player of this.players.values()) {
   195→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   196→                return false;
   197→            }
   198→        }
   199→        return true;
   200→    }
   201→
   202→    // 设置准备状态
   203→    setPlayerReady(playerId, ready) {
   204→        const player = this.players.get(playerId);
   205→        if (player) {
   206→            player.ready = ready;
   207→            this.broadcastPlayerList();
   208→            this.checkStartGame();
   209→        }
   210→    }
   211→
   212→    // 检查是否可以开始游戏
   213→    checkStartGame() {
   214→        const allReady = Array.from(this.players.values()).every(p => p.ready);
   215→        if (allReady && this.players.size === 4 && !this.gameState.started) {
   216→            // 检查是否需要随机换座位（每隔1小时）
   217→            const timeSinceLastShuffle = Date.now() - this.lastSeatShuffleTime;
   218→            if (timeSinceLastShuffle >= 3600000) { // 1小时 = 3600000毫秒
   219→                this.randomizeSeats();
   220→                this.lastSeatShuffleTime = Date.now();
   221→                this.broadcastMessage('⏰ 游戏已进行1小时，座位已随机更换！');
   222→            }
   223→            this.startGame();
   224→        }
   225→    }
   226→
   227→    // 随机换座位
   228→    randomizeSeats() {
   229→        const playerList = Array.from(this.players.values());
   230→        const seats = [1, 2, 3, 4];
   231→
   232→        // 洗牌座位
   233→        for (let i = seats.length - 1; i > 0; i--) {
   234→            const j = Math.floor(Math.random() * (i + 1));
   235→            [seats[i], seats[j]] = [seats[j], seats[i]];
   236→        }
   237→
   238→        // 分配新座位
   239→        playerList.forEach((player, index) => {
   240→            player.seatNum = seats[index];
   241→        });
   242→
   243→        console.log(`牌桌${this.tableNumber} 座位已随机更换`);
   244→        this.broadcastPlayerList();
   245→    }
   246→
   247→    // 开始游戏
   248→    startGame() {
   249→        this.gameState.started = true;
   250→        this.gameState.gameStartTime = Date.now();
   251→        this.gameState.totalGameTime = 0;
   252→
   253→        // 启动游戏计时器（每秒更新）
   254→        this.gameTimer = setInterval(() => {
   255→            if (this.gameState.started) {
   256→                this.gameState.totalGameTime = Math.floor((Date.now() - this.gameState.gameStartTime) / 1000);
   257→            }
   258→        }, 1000);
   259→
   260→        // 洗牌
   261→        this.gameState.deck = shuffle(createDeck());
   262→
   263→        // 确定万能牌（随机翻一张）
   264→        const wildIndex = Math.floor(Math.random() * this.gameState.deck.length);
   265→        this.gameState.wildCard = this.gameState.deck[wildIndex];
   266→
   267→        // 初始化手牌和展示区
   268→        const playerIds = this.getSortedPlayerIds();
   269→        for (const pid of playerIds) {
   270→            this.gameState.hands[pid] = [];
   271→            this.gameState.showedCards[pid] = { fa: [], gang: [] };
   272→            this.gameState.faUsed[pid] = false;
   273→        }
   274→
   275→        // 发牌：每人4张×3轮，然后每人1张，庄家多1张
   276→        // 庄家是1号位(seatNum=1)，对应索引0
   277→        const dealerIndex = playerIds.findIndex(pid => this.players.get(pid).seatNum === 1);
   278→        this.gameState.dealer = dealerIndex >= 0 ? dealerIndex : 0;
   279→
   280→        // 每人4张×3轮
   281→        for (let round = 0; round < 3; round++) {
   282→            for (const pid of playerIds) {
   283→                for (let i = 0; i < 4; i++) {
   284→                    const card = this.gameState.deck.pop();
   285→                    if (card) this.gameState.hands[pid].push(card);
   286→                }
   287→            }
   288→        }
   289→
   290→        // 每人1张
   291→        for (const pid of playerIds) {
   292→            const card = this.gameState.deck.pop();
   293→            if (card) this.gameState.hands[pid].push(card);
   294→        }
   295→
   296→        // 庄家多拿1张
   297→        const dealerPid = playerIds[this.gameState.dealer];
   298→        const extraCard = this.gameState.deck.pop();
   299→        if (extraCard) this.gameState.hands[dealerPid].push(extraCard);
   300→
   301→        // 庄家先出牌
   302→        this.gameState.currentPlayer = this.gameState.dealer;
   303→
   304→        // 排序手牌
   305→        for (const pid of playerIds) {
   306→            this.sortHand(pid);
   307→        }
   308→
   309→        console.log(`牌桌${this.tableNumber} 游戏开始，万能牌: ${cardName(this.gameState.wildCard)}`);
   310→
   311→        // 先发送发牌动画消息
   312→        this.broadcastDealStart();
   313→
   314→        // 等待发牌动画完成（约5秒）后发送游戏状态
   315→        setTimeout(() => {
   316→            this.broadcastGameState();
   317→        }, 5000);
   318→    }
   319→
   320→    // 广播发牌开始消息
   321→    broadcastDealStart() {
   322→        const message = JSON.stringify({ type: 'dealStart' });
   323→        for (const player of this.players.values()) {
   324→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   325→                player.ws.send(message);
   326→            }
   327→        }
   328→    }
   329→
   330→    // 排序手牌
   331→    sortHand(playerId) {
   332→        const hand = this.gameState.hands[playerId];
   333→        if (!hand) return;
   334→
   335→        const suitOrder = { '筒': 0, '条': 1, '万': 2, '风': 3, '箭': 4 };
   336→        const windOrder = { '东': 0, '南': 1, '西': 2, '北': 3 };
   337→        const arrowOrder = { '中': 0, '发': 1, '白': 2 };
   338→
   339→        hand.sort((a, b) => {
   340→            // 万能牌放最后
   341→            if (this.isWildCard(a) && !this.isWildCard(b)) return 1;
   342→            if (!this.isWildCard(a) && this.isWildCard(b)) return -1;
   343→
   344→            const suitA = suitOrder[a.suit] ?? 5;
   345→            const suitB = suitOrder[b.suit] ?? 5;
   346→            if (suitA !== suitB) return suitA - suitB;
   347→
   348→            if (a.type === 'number' && b.type === 'number') {
   349→                return a.rank - b.rank;
   350→            } else if (a.type === 'wind' && b.type === 'wind') {
   351→                return (windOrder[a.rank] ?? 0) - (windOrder[b.rank] ?? 0);
   352→            } else if (a.type === 'arrow' && b.type === 'arrow') {
   353→                return (arrowOrder[a.rank] ?? 0) - (arrowOrder[b.rank] ?? 0);
   354→            }
   355→            return 0;
   356→        });
   357→    }
   358→
   359→    // 判断是否是万能牌（相同牌或红中）
   360→    isWildCard(card) {
   361→        const wild = this.gameState.wildCard;
   362→        if (!wild) return false;
   363→
   364→        // 相同牌是万能牌
   365→        if (card.suit === wild.suit && card.rank === wild.rank) return true;
   366→        // 红中也是万能牌
   367→        if (card.type === 'arrow' && card.rank === '中') return true;
   368→
   369→        return false;
   370→    }
   371→
   372→    // 摸牌
   373→    drawCard(playerId) {
   374→        if (this.gameState.deck.length === 0) {
   375→            return null; // 流局
   376→        }
   377→
   378→        const card = this.gameState.deck.pop();
   379→        if (card) {
   380→            this.gameState.hands[playerId].push(card);
   381→            this.gameState.lastDrawn = card;
   382→            this.sortHand(playerId);
   383→        }
   384→        return card;
   385→    }
   386→
   387→    // 出牌
   388→    playCard(playerId, cardId) {
   389→        const hand = this.gameState.hands[playerId];
   390→        if (!hand) return false;
   391→
   392→        const cardIndex = hand.findIndex(c => c.id === cardId);
   393→        if (cardIndex === -1) return false;
   394→
   395→        const card = hand.splice(cardIndex, 1)[0];
   396→
   397→        // 打出的牌背面朝上，加入弃牌堆
   398→        this.gameState.discardedPile.push({
   399→            playerId,
   400→            card,
   401→            hidden: true // 背面朝上
   402→        });
   403→
   404→        // 下一位玩家
   405→        this.nextPlayer();
   406→
   407→        return true;
   408→    }
   409→
   410→    // 换牌（发或红中）
   411→    changeFa(playerId) {
   412→        // 检查是否已换过
   413→        if (this.gameState.faUsed[playerId]) return false;
   414→
   415→        const hand = this.gameState.hands[playerId];
   416→        if (!hand) return false;
   417→
   418→        const wild = this.gameState.wildCard;
   419→        const isWildFa = wild && wild.type === 'arrow' && wild.rank === '发';
   420→
   421→        // 如果万能牌是"发"，找红中；否则找"发"
   422→        let targetRank = isWildFa ? '中' : '发';
   423→        const faIndex = hand.findIndex(c => c.type === 'arrow' && c.rank === targetRank);
   424→        if (faIndex === -1) return false;
   425→
   426→        // 移出牌到展示区
   427→        const faCard = hand.splice(faIndex, 1)[0];
   428→        this.gameState.showedCards[playerId].fa.push(faCard);
   429→        this.gameState.faUsed[playerId] = true;
   430→
   431→        // 摸一张新牌
   432→        const newCard = this.drawCard(playerId);
   433→
   434→        return { faCard, newCard };
   435→    }
   436→
   437→    // 暗杠
   438→    doGang(playerId, cardId) {
   439→        const hand = this.gameState.hands[playerId];
   440→        if (!hand) return false;
   441→
   442→        // 找到这张牌
   443→        const targetCard = hand.find(c => c.id === cardId);
   444→        if (!targetCard) return false;
   445→
   446→        // 找所有相同的牌（不包括万能牌替代）
   447→        const sameCards = hand.filter(c =>
   448→            c.suit === targetCard.suit && c.rank === targetCard.rank
   449→        );
   450→
   451→        if (sameCards.length !== 4) return false;
   452→
   453→        // 移除这4张牌
   454→        this.gameState.hands[playerId] = hand.filter(c =>
   455→            !(c.suit === targetCard.suit && c.rank === targetCard.rank)
   456→        );
   457→
   458→        // 加入展示区
   459→        this.gameState.showedCards[playerId].gang.push(sameCards);
   460→
   461→        return sameCards;
   462→    }
   463→
   464→    // 检查是否可以暗杠
   465→    canGang(playerId) {
   466→        const hand = this.gameState.hands[playerId];
   467→        if (!hand) return [];
   468→
   469→        const counts = {};
   470→        for (const card of hand) {
   471→            const key = `${card.suit}_${card.rank}`;
   472→            counts[key] = (counts[key] || 0) + 1;
   473→        }
   474→
   475→        const gangable = [];
   476→        for (const [key, count] of Object.entries(counts)) {
   477→            if (count === 4) {
   478→                const [suit, rank] = key.split('_');
   479→                gangable.push({ suit, rank });
   480→            }
   481→        }
   482→
   483→        return gangable;
   484→    }
   485→
   486→    // 检查是否有牌可以换（发或红中）
   487→    hasFa(playerId) {
   488→        const hand = this.gameState.hands[playerId];
   489→        if (!hand) return false;
   490→
   491→        // 如果已经换过，不能换
   492→        if (this.gameState.faUsed[playerId]) return false;
   493→
   494→        const wild = this.gameState.wildCard;
   495→        const isWildFa = wild && wild.type === 'arrow' && wild.rank === '发';
   496→
   497→        // 如果万能牌是"发"，用红中换牌；否则用"发"换牌
   498→        if (isWildFa) {
   499→            return hand.some(c => c.type === 'arrow' && c.rank === '中');
   500→        } else {
   501→            return hand.some(c => c.type === 'arrow' && c.rank === '发');
   502→        }
   503→    }
   504→
   505→    // 获取当前用于换牌的牌名（发或中）
   506→    getExchangeCardName() {
   507→        const wild = this.gameState.wildCard;
   508→        const isWildFa = wild && wild.type === 'arrow' && wild.rank === '发';
   509→        return isWildFa ? '中' : '发';
   510→    }
   511→
   512→    // 下一位玩家
   513→    nextPlayer() {
   514→        this.gameState.currentPlayer = (this.gameState.currentPlayer + 1) % 4;
   515→    }
   516→
   517→    // 获取当前玩家ID
   518→    getCurrentPlayerId() {
   519→        const playerIds = this.getSortedPlayerIds();
   520→        return playerIds[this.gameState.currentPlayer];
   521→    }
   522→
   523→    // 广播玩家列表
   524→    broadcastPlayerList() {
   525→        const players = Array.from(this.players.values()).map(p => ({
   526→            id: p.id,
   527→            name: p.name,
   528→            seatNum: p.seatNum,
   529→            ready: p.ready,
   530→            isAI: p.isAI
   531→        }));
   532→
   533→        const message = JSON.stringify({
   534→            type: 'playerList',
   535→            players,
   536→            tableNumber: this.tableNumber,
   537→            started: this.gameState.started
   538→        });
   539→
   540→        for (const player of this.players.values()) {
   541→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   542→                player.ws.send(message);
   543→            }
   544→        }
   545→
   546→        for (const spectator of this.spectators.values()) {
   547→            if (spectator.ws && spectator.ws.readyState === WebSocket.OPEN) {
   548→                spectator.ws.send(message);
   549→            }
   550→        }
   551→    }
   552→
   553→    // 广播游戏状态
   554→    broadcastGameState() {
   555→        const playerIds = this.getSortedPlayerIds();
   556→
   557→        // 调试：打印万能牌信息
   558→        console.log(`广播游戏状态，万能牌: ${JSON.stringify(this.gameState.wildCard)}`);
   559→
   560→        for (const [playerId, player] of this.players) {
   561→            if (!player.ws || player.ws.readyState !== WebSocket.OPEN) continue;
   562→
   563→            const state = this.getPlayerGameState(playerId);
   564→            console.log(`发送游戏状态给 ${player.name}: 手牌数量=${state.myHand.length}, 万能牌: ${JSON.stringify(state.wildCard)}`);
   565→            player.ws.send(JSON.stringify({
   566→                type: 'gameState',
   567→                data: state
   568→            }));
   569→        }
   570→    }
   571→
   572→    // 获取单个玩家视角的游戏状态
   573→    getPlayerGameState(playerId) {
   574→        const playerIds = this.getSortedPlayerIds();
   575→        const myIndex = playerIds.indexOf(playerId);
   576→
   577→        // 构建各玩家信息
   578→        const playerInfo = {};
   579→        for (let i = 0; i < playerIds.length; i++) {
   580→            const pid = playerIds[i];
   581→            const p = this.players.get(pid);
   582→            playerInfo[pid] = {
   583→                name: p?.name || '',
   584→                seatNum: p?.seatNum || (i + 1),
   585→                handCount: this.gameState.hands[pid]?.length || 0,
   586→                showedCards: this.gameState.showedCards[pid] || { fa: [], gang: [] }
   587→            };
   588→        }
   589→
   590→        // 只返回自己的手牌
   591→        const myHand = this.gameState.hands[playerId] || [];
   592→
   593→        // 获取当前玩家的座位号
   594→        const currentPid = playerIds[this.gameState.currentPlayer];
   595→        const currentPlayerSeat = this.players.get(currentPid)?.seatNum || 1;
   596→
   597→        // 获取庄家的座位号
   598→        const dealerPid = playerIds[this.gameState.dealer];
   599→        const dealerSeat = this.players.get(dealerPid)?.seatNum || 1;
   600→
   601→        return {
   602→            started: this.gameState.started,
   603→            currentPlayer: this.gameState.currentPlayer,
   604→            currentPlayerSeat,
   605→            dealer: this.gameState.dealer,
   606→            dealerSeat,
   607→            myIndex,
   608→            myHand,
   609→            wildCard: this.gameState.wildCard,
   610→            deckCount: this.gameState.deck.length,
   611→            totalGameTime: this.gameState.totalGameTime,
   612→            playerInfo,
   613→            discardedCount: this.gameState.discardedPile.length,
   614→            canChangeFa: this.hasFa(playerId) && this.getCurrentPlayerId() === playerId,
   615→            canGang: this.canGang(playerId).length > 0 && this.getCurrentPlayerId() === playerId
   616→        };
   617→    }
   618→
   619→    // 广播消息
   620→    broadcastMessage(text) {
   621→        const message = JSON.stringify({ type: 'message', text });
   622→        for (const player of this.players.values()) {
   623→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   624→                player.ws.send(message);
   625→            }
   626→        }
   627→    }
   628→
   629→    // 获取牌桌信息（用于大厅显示）
   630→    getTableInfo() {
   631→        return {
   632→            id: this.id,
   633→            tableNumber: this.tableNumber,
   634→            playerCount: this.players.size,
   635→            maxPlayers: this.maxPlayers,
   636→            started: this.gameState.started,
   637→            deckCount: this.gameState.deck ? this.gameState.deck.length : 0,
   638→            players: Array.from(this.players.values()).map(p => ({
   639→                name: p.name,
   640→                seatNum: p.seatNum,
   641→                ready: p.ready
   642→            }))
   643→        };
   644→    }
   645→}
   646→
   647→// ==================== WebSocket连接处理 ====================
   648→wss.on('connection', (ws) => {
   649→    let playerId = null;
   650→    let playerName = null;
   651→    let currentTableId = null;
   652→
   653→    console.log('新客户端连接');
   654→
   655→    ws.on('message', (data) => {
   656→        try {
   657→            const msg = JSON.parse(data);
   658→
   659→            switch (msg.type) {
   660→                case 'login':
   661→                    playerId = `player_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
   662→                    playerName = msg.name || '玩家';
   663→
   664→                    // 添加到已登录客户端集合
   665→                    loggedInClients.add(ws);
   666→
   667→                    ws.send(JSON.stringify({
   668→                        type: 'loginSuccess',
   669→                        playerId,
   670→                        playerName
   671→                    }));
   672→
   673→                    // 发送牌桌列表
   674→                    sendTableList(ws);
   675→                    break;
   676→
   677→                case 'getTableList':
   678→                    sendTableList(ws);
   679→                    break;
   680→
   681→                case 'createTable':
   682→                    const newTable = createTable();
   683→                    // 加入牌桌
   684→                    if (joinTable(ws, playerId, playerName, newTable.id, msg.seatNum)) {
   685→                        currentTableId = newTable.id;
   686→                    }
   687→                    // 广播牌桌列表更新给所有人
   688→                    broadcastTableList();
   689→                    break;
   690→
   691→                case 'joinTable':
   692→                    if (joinTable(ws, playerId, playerName, msg.tableId, msg.seatNum)) {
   693→                        currentTableId = msg.tableId;
   694→                        // 广播牌桌列表更新给所有人
   695→                        broadcastTableList();
   696→                    }
   697→                    break;
   698→
   699→                case 'ready':
   700→                    if (currentTableId) {
   701→                        const table = tables.get(currentTableId);
   702→                        if (table) {
   703→                            table.setPlayerReady(playerId, msg.ready);
   704→                        }
   705→                    }
   706→                    break;
   707→
   708→                case 'play':
   709→                    if (currentTableId) {
   710→                        const table = tables.get(currentTableId);
   711→                        if (table && table.getCurrentPlayerId() === playerId) {
   712→                            if (table.playCard(playerId, msg.cardId)) {
   713→                                table.broadcastGameState();
   714→                            }
   715→                        }
   716→                    }
   717→                    break;
   718→
   719→                case 'changeFa':
   720→                    if (currentTableId) {
   721→                        const table = tables.get(currentTableId);
   722→                        if (table && table.getCurrentPlayerId() === playerId) {
   723→                            const result = table.changeFa(playerId);
   724→                            if (result) {
   725→                                table.broadcastMessage(`${playerName} 换了一张"發"`);
   726→                                table.broadcastGameState();
   727→                            }
   728→                        }
   729→                    }
   730→                    break;
   731→
   732→                case 'gang':
   733→                    if (currentTableId) {
   734→                        const table = tables.get(currentTableId);
   735→                        if (table && table.getCurrentPlayerId() === playerId) {
   736→                            const result = table.doGang(playerId, msg.cardId);
   737→                            if (result) {
   738→                                table.broadcastMessage(`${playerName} 暗杠！`);
   739→                                table.broadcastGameState();
   740→                            }
   741→                        }
   742→                    }
   743→                    break;
   744→
   745→                case 'draw':
   746→                    if (currentTableId) {
   747→                        const table = tables.get(currentTableId);
   748→                        if (table && table.getCurrentPlayerId() === playerId) {
   749→                            const card = table.drawCard(playerId);
   750→                            if (card) {
