   753→                                table.broadcastMessage('牌堆已空，流局！');
   754→                            }
   755→                        }
   756→                    }
   757→                    break;
   758→
   759→                case 'chat':
   760→                    if (currentTableId) {
   761→                        const table = tables.get(currentTableId);
   762→                        if (table) {
   763→                            table.broadcastMessage(`${playerName}: ${msg.text}`);
   764→                        }
   765→                    }
   766→                    break;
   767→            }
   768→        } catch (e) {
   769→            console.error('消息处理错误:', e);
   770→        }
   771→    });
   772→
   773→    ws.on('close', () => {
   774→        console.log('客户端断开:', playerName);
   775→
   776→        // 从已登录客户端集合中移除
   777→        loggedInClients.delete(ws);
   778→
   779→        if (currentTableId && playerId) {
   780→            const table = tables.get(currentTableId);
   781→            if (table) {
   782→                // 标记玩家断开
   783→                const player = table.players.get(playerId);
   784→                if (player) {
   785→                    player.ws = null;
   786→                    player.ready = false;
   787→                }
   788→
   789→                // 如果游戏未开始，直接移除玩家
   790→                if (!table.gameState.started) {
   791→                    table.removePlayer(playerId);
   792→                }
   793→
   794→                // 检查是否所有玩家都已断开连接，如果是则删除房间
   795→                if (table.isAllPlayersDisconnected()) {
   796→                    tables.delete(currentTableId);
   797→                    console.log(`牌桌 ${currentTableId} 所有人已离开，自动解散`);
   798→                } else {
   799→                    table.broadcastPlayerList();
   800→                }
   801→            }
   802→            playerToTable.delete(playerId);
   803→
   804→            // 广播牌桌列表更新（因为有人离开）
   805→            broadcastTableList();
   806→        }
   807→    });
   808→});
   809→
   810→// 发送牌桌列表
   811→function sendTableList(ws) {
   812→    const tableList = Array.from(tables.values()).map(t => t.getTableInfo());
   813→    ws.send(JSON.stringify({
   814→        type: 'tableList',
   815→        tables: tableList
   816→    }));
   817→}
   818→
   819→// 广播牌桌列表给所有已登录客户端
   820→function broadcastTableList() {
   821→    const tableList = Array.from(tables.values()).map(t => t.getTableInfo());
   822→    const message = JSON.stringify({
   823→        type: 'tableList',
   824→        tables: tableList
   825→    });
   826→
   827→    // 广播给所有连接的客户端
   828→    let count = 0;
   829→    wss.clients.forEach(client => {
   830→        if (client.readyState === WebSocket.OPEN) {
   831→            client.send(message);
   832→            count++;
   833→        }
   834→    });
   835→    console.log(`广播牌桌列表给 ${count} 个客户端，当前牌桌数: ${tableList.length}`);
   836→}
   837→
   838→// 创建牌桌
   839→function createTable() {
   840→    tableCounter++;
   841→    const tableId = `table_${tableCounter}`;
   842→    const table = new GameTable(tableId, tableCounter);
   843→    tables.set(tableId, table);
   844→    console.log(`创建新牌桌: ${tableId}`);
   845→    return table;
   846→}
   847→
   848→// 加入牌桌
   849→function joinTable(ws, playerId, playerName, tableId, seatNum) {
   850→    const table = tables.get(tableId);
   851→    if (!table) {
   852→        ws.send(JSON.stringify({ type: 'error', message: '牌桌不存在' }));
   853→        return false;
   854→    }
   855→
   856→    if (table.addPlayer(ws, playerId, playerName, seatNum)) {
   857→        playerToTable.set(playerId, tableId);
   858→        table.broadcastPlayerList();
   859→        console.log(`${playerName} 加入牌桌 ${tableId}`);
   860→        return true;
   861→    } else {
   862→        ws.send(JSON.stringify({ type: 'error', message: '无法加入牌桌（已满或游戏已开始）' }));
   863→        return false;
   864→    }
   865→}
   866→
   867→// 获取本机IP
   868→function getLocalIP() {
   869→    const os = require('os');
   870→    const interfaces = os.networkInterfaces();
   871→
   872→    for (const name of Object.keys(interfaces)) {
   873→        for (const iface of interfaces[name]) {
   874→            if (iface.family === 'IPv4' && !iface.internal) {
   875→                return iface.address;
   876→            }
   877→        }
   878→    }
   879→    return 'localhost';
