   888→    console.log(`LAN URL: http://${localIP}:${PORT}`);
   889→    console.log('');
   890→});
   891→
   892→// 定时清理空桌子（每5分钟检查一次）
   893→setInterval(() => {
   894→    for (const [tableId, table] of tables) {
   895→        // 如果桌子没有玩家，或者所有玩家都已断开连接
   896→        if (table.players.size === 0) {
   897→            tables.delete(tableId);
   898→            console.log(`Cleaned up empty table: ${tableId}`);
   899→        } else {
   900→            // 检查是否所有玩家都已断开
   901→            let allDisconnected = true;
   902→            for (const player of table.players.values()) {
