        /* 万能牌样式 - 癞子 */
        .card.wild {
            background: linear-gradient(180deg, #fff8e1 0%, #ffecb3 50%, #ffe082 100%);
            border: 2px solid #ffa000;
            box-shadow:
                1px 0 0 #ff8f00,
                0 2px 0 #f57c00,
                0 3px 0 #ef6c00,
                0 4px 0 #e65100,
                0 5px 3px rgba(255,152,0,0.4),
                0 0 10px rgba(255,160,0,0.5);
        }

        /* 癞子标记 */
        .card.wild::before {
            content: '癞';
            position: absolute;
            top: -2px;
            right: -2px;
            width: 13px;
            height: 13px;
            background: linear-gradient(135deg, #ff5722 0%, #e64a19 100%);
            color: white;
            font-size: 8px;
            font-weight: bold;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 0 3px 0 4px;
            box-shadow: -1px 1px 2px rgba(0,0,0,0.3);
            z-index: 5;
            line-height: 1;
        }

        /* 牌面内容容器 */
        .card-face {
            width: 28px;
            height: 40px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            background: #fafaf5;
            border-radius: 2px;
            box-shadow: inset 0 0 2px rgba(0,0,0,0.05);
            border: 1px solid #e8e0d8;
        }

        /* 筒子牌 - 圆点图案 */
        .card.tong .card-face {
            position: relative;
        }

        .card.tong .dot-container {
            width: 24px;
            height: 32px;
            display: grid;
            place-items: center;
        }

        .card.tong .dot {
            width: 6px;
            height: 6px;
            background: radial-gradient(circle at 40% 40%, #90caf9, #1976d2 70%, #0d47a1);
            border-radius: 50%;
            box-shadow:
                inset 0 1px 2px rgba(255,255,255,0.5),
                0 1px 1px rgba(0,0,0,0.15);
        }

        /* 1筒 - 大圆带花边 */
        .card.tong.p1 .dot-container {
            display: flex;
            align-items: center;
            justify-content: center;
        }
        .card.tong.p1 .dot {
            width: 12px;
            height: 12px;
            background: radial-gradient(circle at 40% 40%, #64b5f6, #1976d2 60%, #0d47a1);
            box-shadow:
                inset 0 1px 3px rgba(255,255,255,0.6),
                inset 0 -1px 2px rgba(0,0,0,0.2),
                0 1px 2px rgba(0,0,0,0.15);
        }

        /* 2筒 */
        .card.tong.p2 .dot-container {
            display: flex;
            flex-direction: column;
            gap: 5px;
        }

        /* 3筒 */
        .card.tong.p3 .dot-container {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            grid-template-rows: repeat(2, 1fr);
            gap: 1px;
        }
        .card.tong.p3 .dot:nth-child(1) { grid-column: 1; grid-row: 1; }
        .card.tong.p3 .dot:nth-child(2) { grid-column: 2; grid-row: 1; }
        .card.tong.p3 .dot:nth-child(3) { grid-column: 1 / 3; grid-row: 2; justify-self: center; }

        /* 4筒 */
        .card.tong.p4 .dot-container {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            grid-template-rows: repeat(2, 1fr);
            gap: 4px;
            padding: 2px;
        }

        /* 5筒 */
        .card.tong.p5 .dot-container {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            grid-template-rows: repeat(3, 1fr);
            gap: 1px;
        }
        .card.tong.p5 .dot:nth-child(1) { grid-column: 1; grid-row: 1; }
        .card.tong.p5 .dot:nth-child(2) { grid-column: 3; grid-row: 1; }
        .card.tong.p5 .dot:nth-child(3) { grid-column: 2; grid-row: 2; width: 8px; height: 8px; }
        .card.tong.p5 .dot:nth-child(4) { grid-column: 1; grid-row: 3; }
        .card.tong.p5 .dot:nth-child(5) { grid-column: 3; grid-row: 3; }

        /* 6筒 */
        .card.tong.p6 .dot-container {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            grid-template-rows: repeat(3, 1fr);
            gap: 2px;
        }

        /* 7筒 */
        .card.tong.p7 .dot-container {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            grid-template-rows: repeat(3, 1fr);
            gap: 1px;
        }
        .card.tong.p7 .dot:nth-child(1) { grid-column: 2; grid-row: 1; }
        .card.tong.p7 .dot:nth-child(2) { grid-column: 1; grid-row: 2; }
        .card.tong.p7 .dot:nth-child(3) { grid-column: 3; grid-row: 2; }
        .card.tong.p7 .dot:nth-child(4) { grid-column: 1; grid-row: 3; }
        .card.tong.p7 .dot:nth-child(5) { grid-column: 2; grid-row: 3; }
        .card.tong.p7 .dot:nth-child(6) { grid-column: 3; grid-row: 3; }
        .card.tong.p7 .dot:nth-child(7) { grid-column: 2; grid-row: 2; width: 8px; height: 8px; }

        /* 8筒 */
        .card.tong.p8 .dot-container {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            grid-template-rows: repeat(3, 1fr);
            gap: 1px;
        }
        .card.tong.p8 .dot:nth-child(4) { grid-column: 2; grid-row: 2; display: none; }
        .card.tong.p8 .dot { width: 5px; height: 5px; }

        /* 9筒 */
        .card.tong.p9 .dot-container {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            grid-template-rows: repeat(3, 1fr);
            gap: 2px;
        }
        .card.tong.p9 .dot { width: 5px; height: 5px; }

        /* 条子牌 - 竹节图案 */
        .card.tiao .card-face {
            padding: 2px;
        }
        .card.tiao .bamboo-container {
            display: flex;
            flex-direction: column;
            gap: 1px;
            align-items: center;
        }
        .card.tiao .bamboo-stick {
            width: 4px;
            height: 6px;
            background: linear-gradient(90deg, #2e7d32, #4caf50 40%, #66bb6a 50%, #4caf50 60%, #2e7d32);
            border-radius: 1px;
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.3),
                0 1px 1px rgba(0,0,0,0.1);
        }
        .card.tiao .bamboo-row {
            display: flex;
            gap: 2px;
        }

        /* 万子牌 */
        .card.wan .card-face {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 0px;
        }
        .card.wan .wan-num {
            font-size: 14px;
            font-weight: bold;
            color: #c62828;
            line-height: 1;
            font-family: 'KaiTi', 'STKaiti', 'SimSun', serif;
        }
        .card.wan .wan-char {
            font-size: 10px;
            color: #c62828;
            font-weight: bold;
            font-family: 'KaiTi', 'STKaiti', 'SimSun', serif;
        }

        /* 风牌 */
        .card.feng .card-face {
            display: flex;
            align-items: center;
            justify-content: center;
        }
        .card.feng .feng-char {
            font-size: 18px;
            font-weight: bold;
            color: #1565c0;
            font-family: 'KaiTi', 'STKaiti', 'SimSun', serif;
            text-shadow: 1px 1px 0 rgba(255,255,255,0.5);
        }

        /* 箭牌 */
        .card.jian .card-face {
            display: flex;
            align-items: center;
            justify-content: center;
        }
        .card.jian .jian-char {
            font-size: 18px;
            font-weight: bold;
            font-family: 'KaiTi', 'STKaiti', 'SimSun', serif;
        }

        .card.jian.zhong .jian-char {
            color: #c62828;
            text-shadow: 1px 1px 0 rgba(255,255,255,0.5);
        }
        .card.jian.fa .jian-char {
            color: #2e7d32;
            text-shadow: 1px 1px 0 rgba(255,255,255,0.5);
        }
        .card.jian.bai .jian-char {
            color: #455a64;
            text-shadow: 1px 1px 0 #78909c, -1px -1px 0 #fff;
        }

        /* 兼容旧样式（用于其他区域显示） */
        .card-rank {
            font-size: 14px;
            font-weight: bold;
        }
        .card-suit {
            font-size: 9px;
            color: #666;
        }

        /* 中央信息区 */
        .center-info {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            text-align: center;
            background: rgba(0,0,0,0.7);
            padding: 15px;
            border-radius: 50%;
            width: 200px;
            height: 200px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
        }

        /* 方位标记 */
        .direction-marks {
            position: absolute;
            width: 100%;
            height: 100%;
            top: 0;
            left: 0;
        }

        .direction {
            position: absolute;
            font-size: 16px;
            font-weight: bold;
            color: #FFD700;
        }

        .direction.north { top: 5px; left: 50%; transform: translateX(-50%); }
        .direction.south { bottom: 5px; left: 50%; transform: translateX(-50%); }
        .direction.east { right: 15px; top: 50%; transform: translateY(-50%); }
        .direction.west { left: 15px; top: 50%; transform: translateY(-50%); }

        /* 中央内容 */
        .center-content {
            z-index: 1;
        }

        .beijing-time {
            font-size: 18px;
            font-weight: bold;
            color: #fff;
            text-shadow: 0 0 10px #FFD700;
            margin-bottom: 8px;
        }

        .dice-area {
            display: flex;
            gap: 10px;
            justify-content: center;
            margin-bottom: 8px;
        }

        .dice {
            width: 36px;
            height: 36px;
            background: linear-gradient(135deg, #fff, #ddd);
            border-radius: 6px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 20px;
            font-weight: bold;
            color: #333;
            box-shadow: 2px 2px 5px rgba(0,0,0,0.3);
        }

        .dice.rolling {
            animation: diceRoll 0.5s ease-in-out;
        }

        @keyframes diceRoll {
            0%, 100% { transform: rotate(0deg); }
            25% { transform: rotate(15deg); }
            75% { transform: rotate(-15deg); }
        }

        .roll-dice-btn {
            padding: 5px 12px;
            font-size: 12px;
            background: linear-gradient(135deg, #e74c3c, #c0392b);
            color: #fff;
            border: none;
            border-radius: 15px;
            cursor: pointer;
            transition: all 0.3s;
        }

        .roll-dice-btn:hover {
            transform: scale(1.05);
            box-shadow: 0 0 10px rgba(231, 76, 60, 0.5);
        }

        .roll-dice-btn:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        .wild-card-info {
            margin-top: 8px;
            white-space: nowrap;
        }

        .wild-card-info .label {
            font-size: 12px;
            color: #ccc;
            display: inline;
        }

        .wild-card-info .card-display {
            font-size: 16px;
            font-weight: bold;
            color: #FFD700;
            display: inline;
            margin-left: 5px;
        }

        .deck-count {
            font-size: 12px;
            color: #ccc;
            margin-top: 5px;
        }

        /* 操作按钮 */
        .action-buttons {
            display: flex;
            gap: 10px;
            justify-content: center;
            margin-top: 10px;
            flex-wrap: wrap;
        }

        .action-btn {
            padding: 8px 20px;
            font-size: 14px;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            transition: all 0.3s;
        }

        .action-btn:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        .action-btn.play {
            background: #4CAF50;
            color: white;
        }

        .action-btn.fa {
            background: #FFD700;
            color: #333;
        }

        .action-btn.gang {
            background: #9C27B0;
            color: white;
        }

        .action-btn.hu {
            background: #f44336;
            color: white;
        }

        /* 聊天区域 */
        .chat-area {
            position: absolute;
            bottom: 200px;
            right: 10px;
            width: 200px;
            background: rgba(0,0,0,0.5);
            border-radius: 10px;
            padding: 10px;
        }

        .chat-messages {
            height: 150px;
            overflow-y: auto;
            font-size: 12px;
            margin-bottom: 10px;
        }

        .chat-input {
            display: flex;
            gap: 5px;
        }

        .chat-input input {
            flex: 1;
            padding: 5px;
            border: none;
            border-radius: 3px;
        }

        /* 准备界面 */
        .ready-panel {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: rgba(0,0,0,0.8);
            padding: 30px;
            border-radius: 10px;
            text-align: center;
            z-index: 100;
        }

        .ready-panel h2 {
            margin-bottom: 20px;
        }

        .seat-list {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 10px;
            margin-bottom: 20px;
        }

        .seat-item {
            background: rgba(255,255,255,0.1);
            padding: 10px;
            border-radius: 5px;
        }

        .seat-item.occupied {
            background: rgba(76, 175, 80, 0.3);
        }

        .seat-item.me {
            border: 2px solid #FFD700;
        }

        /* 玩家列表面板 */
        .players-panel {
            position: absolute;
            top: 10px;
            left: 10px;
            background: rgba(0,0,0,0.5);
            padding: 15px;
            border-radius: 10px;
        }

        .players-panel h3 {
            margin-bottom: 10px;
            font-size: 14px;
        }

        .player-item {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 5px 0;
            font-size: 13px;
        }

        .player-item .seat {
            background: rgba(255,255,255,0.2);
            padding: 2px 8px;
            border-radius: 3px;
            font-size: 12px;
        }

        .player-item .ready-status {
            color: #4CAF50;
            font-size: 12px;
        }

        .player-item .not-ready {
            color: #999;
        }

        /* 隐藏 */
        .hidden {
            display: none !important;
        }

        /* 当前玩家指示 */
        .current-turn {
            color: #FFD700 !important;
            font-weight: bold;
        }

        .current-turn::before {
            content: '▶ ';
            color: #FFD700;
        }

        /* 发牌动画 */
        .deal-animation {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0,0,0,0.8);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            z-index: 1000;
        }

        .deal-piles {
            display: flex;
            gap: 20px;
            margin-bottom: 30px;
        }

        .deal-pile {
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        .deal-pile-label {
            color: #fff;
            margin-bottom: 10px;
            font-size: 14px;
        }

        .deal-pile-cards {
            display: flex;
            flex-wrap: wrap;
            width: 120px;
            gap: 2px;
        }

        .deal-card-back {
            width: 25px;
            height: 35px;
            background: linear-gradient(135deg, #1a237e 0%, #283593 100%);
            border-radius: 3px;
            border: 1px solid #3949ab;
        }

        .deal-info {
            color: #FFD700;
            font-size: 24px;
            margin-bottom: 20px;
        }

        .deal-progress {
            color: #fff;
