/* 牌桌列表中的小型圆桌布局 */
.mini-table-layout {
    position: relative;
    width: 120px;
    height: 120px;
    margin: 10px auto;
}

.mini-table-center {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: linear-gradient(135deg, #2d5a3d 0%, #1a3d2a 100%);
    border: 2px solid #FFD700;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
}

.mini-seat {
    position: absolute;
    text-align: center;
    width: 32px;
}

/* 逆时针顺序: 1(底) → 2(右) → 3(顶) → 4(左) */
.mini-seat-1 { bottom: 0; left: 50%; transform: translateX(-50%); }
.mini-seat-2 { right: 0; top: 50%; transform: translateY(-50%); }
.mini-seat-3 { top: 0; left: 50%; transform: translateX(-50%); }
.mini-seat-4 { left: 0; top: 50%; transform: translateY(-50%); }

.mini-seat-avatar {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.2);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: bold;
    border: 2px solid #555;
    transition: all 0.3s;
    color: #fff;
}

.mini-seat-avatar.occupied {
    background: linear-gradient(135deg, #4CAF50, #2E7D32);
    border-color: #81C784;
}

.mini-seat-avatar:hover:not(.occupied) {
    background: rgba(255, 215, 0, 0.3);
    border-color: #FFD700;
    cursor: pointer;
}

.table-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 5px;
}

.table-id {
    color: #FFD700;
    font-size: 14px;
    font-weight: bold;
}

.table-mode-badge {
    font-size: 11px;
    padding: 2px 6px;
    border-radius: 4px;
    background: rgba(255, 215, 0, 0.2);
    color: #FFD700;
}

.table-footer {
    text-align: center;
    font-size: 12px;
    color: #ccc;
    margin-top: 10px;
}

.table-footer.full {
    color: #ff6b6b;
}

.table-footer.playing {
    color: #4dabf7;
}

.deck-info {
    text-align: center;
    font-size: 11px;
    color: #90ee90;
    margin-top: 5px;
    padding: 3px 8px;
    background: rgba(0, 0, 0, 0.3);
    border-radius: 4px;
}

/* 创建新桌卡片样式 */
.create-table-card {
    background: linear-gradient(135deg, rgba(76, 175, 80, 0.3), rgba(46, 125, 50, 0.3));
    border: 2px dashed #4CAF50;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 200px;
}

.create-table-card .plus {
    font-size: 48px;
    color: #4CAF50;
    line-height: 1;
}

.create-table-card .text {
    color: #4CAF50;
    font-size: 16px;
    margin-top: 10px;
}

.create-table-card:hover {
    background: linear-gradient(135deg, rgba(76, 175, 80, 0.5), rgba(46, 125, 50, 0.5));
}

/* 游戏界面样式 */
.game-container {
    display: none;
    width: 100vw;
    height: 100vh;
    position: relative;
}

.game-table {
    width: 100%;
    height: 100%;
    position: relative;
    background: radial-gradient(ellipse at center, #2d5a3d 0%, #1a472a 100%);
}

/* 玩家区域 */
.player-area {
    position: absolute;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.player-area.bottom {
    bottom: 10px;
    left: 50%;
    transform: translateX(-50%);
    width: 80%;
}

.player-area.top {
    top: 10px;
    left: 50%;
    transform: translateX(-50%);
}

.player-area.left {
    left: 10px;
    top: 50%;
    transform: translateY(-50%);
}

.player-area.right {
    right: 10px;
    top: 50%;
    transform: translateY(-50%);
}

.player-info {
    background: rgba(0,0,0,0.5);
    padding: 8px 15px;
    border-radius: 5px;
    margin-bottom: 5px;
    text-align: center;
}

.player-info.active {
    border: 2px solid #FFD700;
    box-shadow: 0 0 10px #FFD700;
}

.player-name {
    font-weight: bold;
}

.hand-count {
    font-size: 0.9em;
    color: #ccc;
}

/* 展示区 */
.showed-area {
    display: flex;
    gap: 5px;
    margin: 5px 0;
    flex-wrap: wrap;
    justify-content: center;
}

.showed-card {
    width: 30px;
    height: 40px;
    background: #fff;
    border-radius: 3px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    color: #333;
}

.showed-card.fa {
    background: #FFD700;
}

.showed-card.gang {
    background: #90EE90;
}

/* 手牌区域 */
.hand-area {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 1px;
    padding: 10px;
    background: linear-gradient(180deg, #1a472a 0%, #0d2818 100%);
    border-radius: 10px;
    max-width: 100%;
    box-shadow: inset 0 2px 8px rgba(0,0,0,0.5);
}

/* 麻将牌基础样式 - 图片中的真实样式 */
.card {
    width: 34px;
    height: 48px;
    background: linear-gradient(180deg, #f5f5f0 0%, #e8e8e0 50%, #ddd8d0 100%);
    border-radius: 3px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.1s ease;
    position: relative;
    box-shadow:
        1px 0 0 #c8c0b8,
        0 2px 0 #d0c8c0,
        0 3px 0 #c0b8b0,
        0 4px 0 #b0a8a0,
        0 5px 3px rgba(0,0,0,0.3);
    border: 1px solid #d8d0c8;
}

.card:hover {
    transform: translateY(-5px);
    box-shadow:
        1px 0 0 #c8c0b8,
        0 3px 0 #d0c8c0,
        0 5px 0 #c0b8b0,
        0 7px 0 #b0a8a0,
        0 9px 6px rgba(0,0,0,0.35);
    z-index: 10;
}

.card.selected {
    transform: translateY(-12px);
    box-shadow:
        1px 0 0 #c8c0b8,
        0 4px 0 #d0c8c0,
        0 7px 0 #c0b8b0,
        0 10px 0 #b0a8a0,
        0 13px 10px rgba(0,0,0,0.4);
    z-index: 20;
}

.card.dragging {
    opacity: 0.6;
    transform: scale(1.1);
}

.card.drag-over {
    border-left: 3px solid #FFD700;
}

/* 万能牌样式 - 癞子 */
.card.wild {
    background: linear-gradient(180deg, #fff8e1 0%, #ffecb3 50%, #ffe082 100%);
    border: 2px solid #ffa000;
    box-shadow:
        1px 0 0 #ff8f00,
        0 2px 0 #f57c00,
        0 3px 0 #ef6c00,
        0 4px 0 #e65100,
        0 5px 3px rgba(255,152,0,0.4),
        0 0 10px rgba(255,160,0,0.5);
}

/* 癞子标记 */
.card.wild::before {
    content: '癞';
    position: absolute;
    top: -2px;
    right: -2px;
    width: 13px;
    height: 13px;
    background: linear-gradient(135deg, #ff5722 0%, #e64a19 100%);
    color: white;
    font-size: 8px;
    font-weight: bold;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 0 3px 0 4px;
    box-shadow: -1px 1px 2px rgba(0,0,0,0.3);
    z-index: 5;
    line-height: 1;
}

/* 牌面内容容器 */
.card-face {
    width: 28px;
    height: 40px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: #fafaf5;
    border-radius: 2px;
    box-shadow: inset 0 0 2px rgba(0,0,0,0.05);
    border: 1px solid #e8e0d8;
}

/* 筒子牌 - 圆点图案 */
.card.tong .card-face {
    position: relative;
}

.card.tong .dot-container {
    width: 24px;
    height: 32px;
    display: grid;
    place-items: center;
}

.card.tong .dot {
    width: 6px;
    height: 6px;
    background: radial-gradient(circle at 40% 40%, #90caf9, #1976d2 70%, #0d47a1);
    border-radius: 50%;
    box-shadow:
        inset 0 1px 2px rgba(255,255,255,0.5),
        0 1px 1px rgba(0,0,0,0.15);
}

/* 1筒 - 大圆带花边 */
.card.tong.p1 .dot-container {
    display: flex;
    align-items: center;
    justify-content: center;
}
.card.tong.p1 .dot {
    width: 12px;
    height: 12px;
    background: radial-gradient(circle at 40% 40%, #64b5f6, #1976d2 60%, #0d47a1);
    box-shadow:
        inset 0 1px 3px rgba(255,255,255,0.6),
        inset 0 -1px 2px rgba(0,0,0,0.2),
        0 1px 2px rgba(0,0,0,0.15);
}

/* 2筒 */
.card.tong.p2 .dot-container {
    display: flex;
    flex-direction: column;
    gap: 5px;
}

/* 3筒 */
.card.tong.p3 .dot-container {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-template-rows: repeat(2, 1fr);
    gap: 1px;
}
.card.tong.p3 .dot:nth-child(1) { grid-column: 1; grid-row: 1; }
.card.tong.p3 .dot:nth-child(2) { grid-column: 2; grid-row: 1; }
.card.tong.p3 .dot:nth-child(3) { grid-column: 1 / 3; grid-row: 2; justify-self: center; }

/* 4筒 */
.card.tong.p4 .dot-container {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-template-rows: repeat(2, 1fr);
    gap: 4px;
    padding: 2px;
}

/* 5筒 */
.card.tong.p5 .dot-container {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    grid-template-rows: repeat(3, 1fr);
    gap: 1px;
}
.card.tong.p5 .dot:nth-child(1) { grid-column: 1; grid-row: 1; }
.card.tong.p5 .dot:nth-child(2) { grid-column: 3; grid-row: 1; }
.card.tong.p5 .dot:nth-child(3) { grid-column: 2; grid-row: 2; width: 8px; height: 8px; }
.card.tong.p5 .dot:nth-child(4) { grid-column: 1; grid-row: 3; }
.card.tong.p5 .dot:nth-child(5) { grid-column: 3; grid-row: 3; }

/* 6筒 */
.card.tong.p6 .dot-container {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-template-rows: repeat(3, 1fr);
    gap: 2px;
}

/* 7筒 */
.card.tong.p7 .dot-container {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    grid-template-rows: repeat(3, 1fr);
    gap: 1px;
}
.card.tong.p7 .dot:nth-child(1) { grid-column: 2; grid-row: 1; }
.card.tong.p7 .dot:nth-child(2) { grid-column: 1; grid-row: 2; }
.card.tong.p7 .dot:nth-child(3) { grid-column: 3; grid-row: 2; }
.card.tong.p7 .dot:nth-child(4) { grid-column: 1; grid-row: 3; }
.card.tong.p7 .dot:nth-child(5) { grid-column: 2; grid-row: 3; }
.card.tong.p7 .dot:nth-child(6) { grid-column: 3; grid-row: 3; }
.card.tong.p7 .dot:nth-child(7) { grid-column: 2; grid-row: 2; width: 8px; height: 8px; }

/* 8筒 */
.card.tong.p8 .dot-container {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    grid-template-rows: repeat(3, 1fr);
    gap: 1px;
}
.card.tong.p8 .dot:nth-child(4) { grid-column: 2; grid-row: 2; display: none; }
.card.tong.p8 .dot { width: 5px; height: 5px; }

/* 9筒 */
.card.tong.p9 .dot-container {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    grid-template-rows: repeat(3, 1fr);
    gap: 2px;
}
.card.tong.p9 .dot { width: 5px; height: 5px; }

/* 条子牌 - 竹节图案 */
.card.tiao .card-face {
    padding: 2px;
}
.card.tiao .bamboo-container {
    display: flex;
    flex-direction: column;
    gap: 1px;
    align-items: center;
}
.card.tiao .bamboo-stick {
    width: 4px;
    height: 6px;
    background: linear-gradient(90deg, #2e7d32, #4caf50 40%, #66bb6a 50%, #4caf50 60%, #2e7d32);
    border-radius: 1px;
    box-shadow:
        inset 0 1px 0 rgba(255,255,255,0.3),
        0 1px 1px rgba(0,0,0,0.1);
}
.card.tiao .bamboo-row {
    display: flex;
    gap: 2px;
}

/* 万子牌 */
.card.wan .card-face {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 0px;
}

