 * 将麻将大图切割成单独的牌图片
 */

const fs = require('fs');
const path = require('path');
const { createCanvas, loadImage } = require('canvas');

// 麻将牌定义
const TILE_NAMES = {
    // 筒子 (第1行: 0-9)
    'tong1': { row: 0, col: 0 },  // 一筒
    'tong2': { row: 0, col: 1 },  // 二筒
    'tong3': { row: 0, col: 2 },  // 三筒
