    'tong5': { row: 0, col: 4 },  // 五筒
    'tong6': { row: 0, col: 5 },  // 六筒
    'tong7': { row: 0, col: 6 },  // 七筒
    'tong8': { row: 0, col: 7 },  // 八筒
    'tong9': { row: 0, col: 8 },  // 九筒

    // 条子 (第2行: 0-8)
    'tiao1': { row: 1, col: 0 },  // 一条
    'tiao2': { row: 1, col: 1 },  // 二条
    'tiao3': { row: 1, col: 2 },  // 三条
    'tiao4': { row: 1, col: 3 },  // 四条
    'tiao5': { row: 1, col: 4 },  // 五条
    'tiao6': { row: 1, col: 5 },  // 六条
    'tiao7': { row: 1, col: 6 },  // 七条
    'tiao8': { row: 1, col: 7 },  // 八条
    'tiao9': { row: 1, col: 8 },  // 九条

    // 万子 (第3行: 0-8)
    'wan1': { row: 2, col: 0 },   // 一万
    'wan2': { row: 2, col: 1 },   // 二万
    'wan3': { row: 2, col: 2 },   // 三万
    'wan4': { row: 2, col: 3 },   // 四万
    'wan5': { row: 2, col: 4 },   // 五万
    'wan6': { row: 2, col: 5 },   // 六万
    'wan7': { row: 2, col: 6 },   // 七万
    'wan8': { row: 2, col: 7 },   // 八万
    'wan9': { row: 2, col: 8 },   // 九万

    // 风牌和箭牌 (第4行)
    'feng_dong': { row: 3, col: 0 },  // 东
    'feng_nan': { row: 3, col: 1 },   // 南
    'feng_xi': { row: 3, col: 2 },    // 西
    'feng_bei': { row: 3, col: 3 },   // 北
    'jian_zhong': { row: 3, col: 4 }, // 中
    'jian_fa': { row: 3, col: 5 },    // 发
    'jian_bai': { row: 3, col: 6 },   // 白
};

async function cutTiles() {
    const sourceImage = path.join(__dirname, '麻将大图.jpg');
    const outputDir = path.join(__dirname, 'tiles');

    // 确保输出目录存在
    if (!fs.existsSync(outputDir)) {
        fs.mkdirSync(outputDir, { recursive: true });
    }

    try {
        const image = await loadImage(sourceImage);
        const imgWidth = image.width;
        const imgHeight = image.height;

        console.log(`图片尺寸: ${imgWidth}x${imgHeight}`);

        // 计算每张牌的尺寸
        const cols = 10;
        const rows = 4;
        const tileWidth = Math.floor(imgWidth / cols);
        const tileHeight = Math.floor(imgHeight / rows);

        console.log(`每张牌尺寸: ${tileWidth}x${tileHeight}`);

        // 切割每张牌
        for (const [name, pos] of Object.entries(TILE_NAMES)) {
            const canvas = createCanvas(tileWidth, tileHeight);
            const ctx = canvas.getContext('2d');

            // 从源图片中截取对应区域
            ctx.drawImage(
                image,
                pos.col * tileWidth,  // 源x
                pos.row * tileHeight, // 源y
                tileWidth,            // 源宽度
                tileHeight,           // 源高度
                0,                    // 目标x
                0,                    // 目标y
                tileWidth,            // 目标宽度
                tileHeight            // 目标高度
            );

            // 保存为PNG
            const buffer = canvas.toBuffer('image/png');
            const outputPath = path.join(outputDir, `${name}.png`);
            fs.writeFileSync(outputPath, buffer);

            console.log(`已保存: ${name}.png`);
        }

        console.log('\n切割完成！共生成 ' + Object.keys(TILE_NAMES).length + ' 张牌');

    } catch (error) {
        console.error('切割失败:', error.message);
        console.log('\n请安装 canvas 模块: npm install canvas');
    }
}

// 如果没有 canvas 模块，使用纯 HTML 方式
function generateHTMLVersion() {
    const html = `<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>麻将牌切割</title>
    <style>
        body { font-family: Arial, sans-serif; padding: 20px; }
        .info { background: #f0f0f0; padding: 10px; margin-bottom: 20px; border-radius: 5px; }
        canvas { border: 1px solid #ccc; display: none; }
        .tiles { display: flex; flex-wrap: wrap; gap: 5px; }
        .tile { width: 60px; height: 90px; border: 1px solid #ccc; }
        button { padding: 10px 20px; font-size: 16px; cursor: pointer; margin: 10px 0; }
        #status { margin-top: 10px; padding: 10px; background: #e0ffe0; }
    </style>
</head>
<body>
    <h1>麻将牌切割工具</h1>
    <div class="info">
        <p>此工具将麻将大图切割成单独的牌图片。</p>
        <p>图片尺寸: 617x373, 每张牌约 61x93 像素</p>
    </div>
    <input type="file" id="fileInput" accept="image/*">
    <br>
    <button onclick="cutTiles()">开始切割</button>
    <div id="status"></div>
    <div class="tiles" id="tiles"></div>
    <canvas id="canvas"></canvas>

    <script>
const TILE_NAMES = {
    'tong1': { row: 0, col: 0, name: '一筒' },
    'tong2': { row: 0, col: 1, name: '二筒' },
    'tong3': { row: 0, col: 2, name: '三筒' },
    'tong4': { row: 0, col: 3, name: '四筒' },
    'tong5': { row: 0, col: 4, name: '五筒' },
    'tong6': { row: 0, col: 5, name: '六筒' },
    'tong7': { row: 0, col: 6, name: '七筒' },
    'tong8': { row: 0, col: 7, name: '八筒' },
    'tong9': { row: 0, col: 8, name: '九筒' },
    'tiao1': { row: 1, col: 0, name: '一条' },
    'tiao2': { row: 1, col: 1, name: '二条' },
    'tiao3': { row: 1, col: 2, name: '三条' },
    'tiao4': { row: 1, col: 3, name: '四条' },
    'tiao5': { row: 1, col: 4, name: '五条' },
    'tiao6': { row: 1, col: 5, name: '六条' },
    'tiao7': { row: 1, col: 6, name: '七条' },
    'tiao8': { row: 1, col: 7, name: '八条' },
    'tiao9': { row: 1, col: 8, name: '九条' },
    'wan1': { row: 2, col: 0, name: '一万' },
    'wan2': { row: 2, col: 1, name: '二万' },
    'wan3': { row: 2, col: 2, name: '三万' },
    'wan4': { row: 2, col: 3, name: '四万' },
    'wan5': { row: 2, col: 4, name: '五万' },
    'wan6': { row: 2, col: 5, name: '六万' },
    'wan7': { row: 2, col: 6, name: '七万' },
    'wan8': { row: 2, col: 7, name: '八万' },
    'wan9': { row: 2, col: 8, name: '九万' },
    'feng_dong': { row: 3, col: 0, name: '东' },
    'feng_nan': { row: 3, col: 1, name: '南' },
    'feng_xi': { row: 3, col: 2, name: '西' },
    'feng_bei': { row: 3, col: 3, name: '北' },
    'jian_zhong': { row: 3, col: 4, name: '中' },
    'jian_fa': { row: 3, col: 5, name: '发' },
    'jian_bai': { row: 3, col: 6, name: '白' },
};

let sourceImage = null;

document.getElementById('fileInput').addEventListener('change', function(e) {
    const file = e.target.files[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = function(event) {
            sourceImage = new Image();
            sourceImage.onload = function() {
                document.getElementById('status').innerHTML =
                    '<strong>图片已加载:</strong> ' + sourceImage.width + 'x' + sourceImage.height;
            };
            sourceImage.src = event.target.result;
        };
        reader.readAsDataURL(file);
    }
});

function cutTiles() {
    if (!sourceImage) {
        alert('请先选择图片文件');
        return;
    }

    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');

    const cols = 10;
    const rows = 4;
    const tileWidth = Math.floor(sourceImage.width / cols);
    const tileHeight = Math.floor(sourceImage.height / rows);

    canvas.width = tileWidth;
    canvas.height = tileHeight;

    const tilesDiv = document.getElementById('tiles');
    tilesDiv.innerHTML = '';

    let count = 0;
    const zip = [];

    for (const [id, pos] of Object.entries(TILE_NAMES)) {
        ctx.clearRect(0, 0, tileWidth, tileHeight);
        ctx.drawImage(
            sourceImage,
            pos.col * tileWidth,
            pos.row * tileHeight,
            tileWidth,
            tileHeight,
            0, 0,
            tileWidth,
            tileHeight
        );

        const dataUrl = canvas.toDataURL('image/png');

        // 显示切割后的牌
        const img = document.createElement('img');
        img.src = dataUrl;
        img.className = 'tile';
        img.title = pos.name;
        tilesDiv.appendChild(img);

        // 准备下载
        zip.push({ name: id + '.png', data: dataUrl });

        count++;
    }

    document.getElementById('status').innerHTML =
        '<strong>切割完成!</strong> 共 ' + count + ' 张牌<br>' +
        '<button onclick="downloadAll()">下载所有图片</button>';

    window.tileData = zip;
}

function downloadAll() {
    if (!window.tileData) return;

    window.tileData.forEach((tile, index) => {
        setTimeout(() => {
            const link = document.createElement('a');
            link.href = tile.data;
            link.download = tile.name;
            link.click();
        }, index * 100);
    });
}
    </script>
</body>
</html>`;

    const htmlPath = path.join(__dirname, 'cut-tiles.html');
    fs.writeFileSync(htmlPath, html);
    console.log('已生成 HTML 版本的切割工具: ' + htmlPath);
    console.log('请在浏览器中打开此文件来切割图片');
}

// 检查 canvas 模块
try {
    require.resolve('canvas');
    cutTiles();
} catch (e) {
    console.log('未安装 canvas 模块，生成 HTML 版本...');
    generateHTMLVersion();
