    'feng_bei': { row: 3, col: 3, name: '北' },
    'jian_zhong': { row: 3, col: 4, name: '中' },
    'jian_fa': { row: 3, col: 5, name: '发' },
    'jian_bai': { row: 3, col: 6, name: '白' },
};

let sourceImage = null;

document.getElementById('fileInput').addEventListener('change', function(e) {
    const file = e.target.files[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = function(event) {
            sourceImage = new Image();
            sourceImage.onload = function() {
                document.getElementById('status').innerHTML =
                    '<strong>图片已加载:</strong> ' + sourceImage.width + 'x' + sourceImage.height;
            };
            sourceImage.src = event.target.result;
        };
        reader.readAsDataURL(file);
    }
});

function cutTiles() {
    if (!sourceImage) {
        alert('请先选择图片文件');
        return;
    }

    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');

    const cols = 10;
    const rows = 4;
    const tileWidth = Math.floor(sourceImage.width / cols);
    const tileHeight = Math.floor(sourceImage.height / rows);

    canvas.width = tileWidth;
    canvas.height = tileHeight;

    const tilesDiv = document.getElementById('tiles');
    tilesDiv.innerHTML = '';

    let count = 0;
    const zip = [];

    for (const [id, pos] of Object.entries(TILE_NAMES)) {
        ctx.clearRect(0, 0, tileWidth, tileHeight);
        ctx.drawImage(
            sourceImage,
            pos.col * tileWidth,
            pos.row * tileHeight,
            tileWidth,
            tileHeight,
            0, 0,
            tileWidth,
            tileHeight
        );

        const dataUrl = canvas.toDataURL('image/png');

        // 显示切割后的牌
        const img = document.createElement('img');
        img.src = dataUrl;
        img.className = 'tile';
        img.title = pos.name;
        tilesDiv.appendChild(img);

        // 准备下载
        zip.push({ name: id + '.png', data: dataUrl });

        count++;
    }

    document.getElementById('status').innerHTML =
        '<strong>切割完成!</strong> 共 ' + count + ' 张牌<br>' +
        '<button onclick="downloadAll()">下载所有图片</button>';

    window.tileData = zip;
}

function downloadAll() {
    if (!window.tileData) return;

    window.tileData.forEach((tile, index) => {
        setTimeout(() => {
            const link = document.createElement('a');
            link.href = tile.data;
            link.download = tile.name;
            link.click();
        }, index * 100);
    });
}
    </script>
</body>
</html>`;

    const htmlPath = path.join(__dirname, 'cut-tiles.html');
