/* 麻将牌基础样式 - 图片中的真实样式 */
.card {
    width: 34px;
    height: 48px;
    background: linear-gradient(180deg, #f5f5f0 0%, #e8e8e0 50%, #ddd8d0 100%);
    border-radius: 3px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.1s ease;
    position: relative;
    box-shadow:
        1px 0 0 #c8c0b8,
        0 2px 0 #d0c8c0,
        0 3px 0 #c0b8b0,
        0 4px 0 #b0a8a0,
        0 5px 3px rgba(0,0,0,0.3);
    border: 1px solid #d8d0c8;
}

.card:hover {
    transform: translateY(-5px);
    box-shadow:
        1px 0 0 #c8c0b8,
        0 3px 0 #d0c8c0,
        0 5px 0 #c0b8b0,
        0 7px 0 #b0a8a0,
        0 9px 6px rgba(0,0,0,0.35);
    z-index: 10;
}

.card.selected {
    transform: translateY(-12px);
    box-shadow:
        1px 0 0 #c8c0b8,
        0 4px 0 #d0c8c0,
        0 7px 0 #c0b8b0,
        0 10px 0 #b0a8a0,
        0 13px 10px rgba(0,0,0,0.4);
    z-index: 20;
}

.card.dragging {
    opacity: 0.6;
    transform: scale(1.1);
}

.card.drag-over {
    border-left: 3px solid #FFD700;
}

/* 万能牌样式 - 癞子 */
.card.wild {
    background: linear-gradient(180deg, #fff8e1 0%, #ffecb3 50%, #ffe082 100%);
    border: 2px solid #ffa000;
    box-shadow:
        1px 0 0 #ff8f00,
        0 2px 0 #f57c00,
        0 3px 0 #ef6c00,
        0 4px 0 #e65100,
        0 5px 3px rgba(255,152,0,0.4),
        0 0 10px rgba(255,160,0,0.5);
}

/* 癞子标记 */
.card.wild::before {
    content: '癞';
    position: absolute;
    top: -2px;
    right: -2px;
    width: 13px;
    height: 13px;
    background: linear-gradient(135deg, #ff5722 0%, #e64a19 100%);
    color: white;
    font-size: 8px;
    font-weight: bold;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 0 3px 0 4px;
    box-shadow: -1px 1px 2px rgba(0,0,0,0.3);
    z-index: 5;
    line-height: 1;
}

/* 牌面内容容器 */
.card-face {
    width: 28px;
    height: 40px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: #fafaf5;
    border-radius: 2px;
    box-shadow: inset 0 0 2px rgba(0,0,0,0.05);
    border: 1px solid #e8e0d8;
}

/* 筒子牌 - 圆点图案 */
.card.tong .card-face {
    position: relative;
}

.card.tong .dot-container {
    width: 24px;
    height: 32px;
    display: grid;
    place-items: center;
}

.card.tong .dot {
    width: 6px;
    height: 6px;
    background: radial-gradient(circle at 40% 40%, #90caf9, #1976d2 70%, #0d47a1);
    border-radius: 50%;
    box-shadow:
        inset 0 1px 2px rgba(255,255,255,0.5),
        0 1px 1px rgba(0,0,0,0.15);
}

