input.old_string:
/* 麻将牌精灵图样式 */
.tile-sprite {
    --tile-width: 61px;
    --tile-height: 93px;
    --scale: 0.6;
    width: calc(var(--tile-width) * var(--scale));
    height: calc(var(--tile-height) * var(--scale));
    background-image: url('麻将大图.jpg');
    background-size: calc(1000px * var(--scale)) calc(600px * var(--scale));
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.1s ease;
    position: relative;
    box-shadow:
        1px 0 0 #c8c0b8,
        0 2px 0 #d0c8c0,
        0 3px 0 #c0b8b0,
        0 4px 0 #b0a8a0,
        0 5px 3px rgba(0,0,0,0.3);
    border: 1px solid #d8d0c8;
    flex-shrink: 0;
}

