/* 麻将牌精灵图样式 */
.tile-sprite {
    --tile-width: 61.7px;
    --tile-height: 93.25px;
    --scale: 0.65;
    width: calc(var(--tile-width) * var(--scale));
    height: calc(var(--tile-height) * var(--scale));
    background-image: url('麻将大图.jpg');
    background-size: calc(617px * var(--scale)) calc(373px * var(--scale));
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.1s ease;
    position: relative;
    box-shadow:
        1px 0 0 #c8c0b8,
        0 2px 0 #d0c8c0,
        0 3px 0 #c0b8b0,
        0 4px 0 #b0a8a0,
        0 5px 3px rgba(0,0,0,0.3);
    border: 1px solid #d8d0c8;
    flex-shrink: 0;
}

.tile-sprite:hover {
    transform: translateY(-5px);
    box-shadow:
        1px 0 0 #c8c0b8,
        0 3px 0 #d0c8c0,
        0 5px 0 #c0b8b0,
        0 7px 0 #b0a8a0,
        0 9px 6px rgba(0,0,0,0.35);
    z-index: 10;
}

.tile-sprite.selected {
    transform: translateY(-12px);
    box-shadow:
        1px 0 0 #c8c0b8,
        0 4px 0 #d0c8c0,
        0 7px 0 #c0b8b0,
        0 10px 0 #b0a8a0,
        0 13px 10px rgba(0,0,0,0.4);
    z-index: 20;
}

