file.content:
    padding: 10px;
    background: linear-gradient(180deg, #1a472a 0%, #0d2818 100%);
    border-radius: 10px;
    max-width: 100%;
    box-shadow: inset 0 2px 8px rgba(0,0,0,0.5);
}

/* 麻将牌精灵图样式 */
.tile-sprite {
    --tile-width: 61.7px;
    --tile-height: 93.25px;
    --scale: 0.65;
    width: calc(var(--tile-width) * var(--scale));
    height: calc(var(--tile-height) * var(--scale));
    background-image: url('麻将大图.jpg');
    background-size: calc(617px * var(--scale)) calc(373px * var(--scale));
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.1s ease;
    position: relative;
    box-shadow:
        1px 0 0 #c8c0b8,
        0 2px 0 #d0c8c0,
        0 3px 0 #c0b8b0,
        0 4px 0 #b0a8a0,
        0 5px 3px rgba(0,0,0,0.3);
    border: 1px solid #d8d0c8;
    flex-shrink: 0;
}

.tile-sprite:hover {
    transform: translateY(-5px);
    box-shadow:
        1px 0 0 #c8c0b8,
        0 3px 0 #d0c8c0,
        0 5px 0 #c0b8b0,
        0 7px 0 #b0a8a0,
        0 9px 6px rgba(0,0,0,0.35);
    z-index: 10;
}

.tile-sprite.selected {
    transform: translateY(-12px);
    box-shadow:
        1px 0 0 #c8c0b8,
        0 4px 0 #d0c8c0,
        0 7px 0 #c0b8b0,
        0 10px 0 #b0a8a0,
        0 13px 10px rgba(0,0,0,0.4);
    z-index: 20;
}

/* 万能牌样式 - 癞子 */
.tile-sprite.wild {
    border: 2px solid #ffa000;
    box-shadow:
        1px 0 0 #ff8f00,
        0 2px 0 #f57c00,
        0 3px 0 #ef6c00,
        0 4px 0 #e65100,
        0 5px 3px rgba(255,152,0,0.4),
        0 0 10px rgba(255,160,0,0.5);
}

/* 癞子标记 */
.tile-sprite.wild::before {
    content: '癞';
    position: absolute;
    top: -2px;
    right: -2px;
    width: 14px;
    height: 14px;
    background: linear-gradient(135deg, #ff5722 0%, #e64a19 100%);
    color: white;
    font-size: 9px;
    font-weight: bold;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 0 3px 0 4px;
    box-shadow: -1px 1px 2px rgba(0,0,0,0.3);
    z-index: 5;
    line-height: 1;
}

