input.old_string:
/* 麻将牌精灵图样式 */
.tile-sprite {
    /* 精灵图参数：图片617x373，4行9列，每张牌约68.5x93.25像素 */
    /* 考虑每张牌有约3像素的白色外框边距 */
    --tile-width: 68.5px;      /* 每张牌在精灵图中的宽度（含边距） */
    --tile-height: 93.25px;    /* 每张牌在精灵图中的高度 */
    --content-width: 62px;     /* 牌内容宽度（不含外边距） */
    --content-height: 87px;    /* 牌内容高度（不含外边距） */
    --scale: 0.65;
    --offset-x: 3px;           /* 水平偏移，跳过左边白色边框 */
    --offset-y: 3px;           /* 垂直偏移，跳过顶部白色边框 */
    width: calc(var(--content-width) * var(--scale));
    height: calc(var(--content-height) * var(--scale));
    background-image: url('麻将大图.jpg');
    background-size: calc(617px * var(--scale)) calc(373px * var(--scale));
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.1s ease;
    position: relative;
    box-shadow:
        1px 0 0 #c8c0b8,
        0 2px 0 #d0c8c0,
        0 3px 0 #c0b8b0,
        0 4px 0 #b0a8a0,
        0 5px 3px rgba(0,0,0,0.3);
    border: 1px solid #d8d0c8;
    flex-shrink: 0;
}

