// 桐城自摸麻将 - 局域网服务器
// 运行方式: node majiang-server.js

const http = require('http');
const fs = require('fs');
const path = require('path');
const WebSocket = require('ws');

const PORT = 8082;

// ==================== HTTP服务器 ====================
const server = http.createServer((req, res) => {
    console.log(`HTTP请求: ${req.url}`);

    // 解码URL（处理中文文件名）
    const decodedUrl = decodeURIComponent(req.url);

    if (req.url === '/' || req.url === '/index.html') {
        const htmlPath = path.join(__dirname, 'majiang-lan.html');
        fs.readFile(htmlPath, (err, data) => {
            if (err) {
                res.writeHead(404);
                res.end('游戏文件未找到');
                return;
            }
            res.writeHead(200, {
                'Content-Type': 'text/html; charset=utf-8'
            });
            res.end(data);
        });
    } else if (req.url === '/favicon.ico') {
        res.writeHead(204);
        res.end();
    } else if (decodedUrl.endsWith('.jpg') || decodedUrl.endsWith('.jpeg') || decodedUrl.endsWith('.png') || decodedUrl.endsWith('.gif')) {
        // 处理图片文件
        const imagePath = path.join(__dirname, decodedUrl);
        fs.readFile(imagePath, (err, data) => {
            if (err) {
                console.log(`图片未找到: ${imagePath}`);
                res.writeHead(404);
                res.end('图片未找到');
                return;
            }
            const ext = path.extname(decodedUrl).toLowerCase();
            const contentTypes = {
                '.jpg': 'image/jpeg',
                '.jpeg': 'image/jpeg',
                '.png': 'image/png',
                '.gif': 'image/gif'
            };
            res.writeHead(200, {
                'Content-Type': contentTypes[ext] || 'application/octet-stream'
            });
            res.end(data);
        });
    } else {
        res.writeHead(404);
        res.end('Not Found');
    }
});

