/* 麻将牌精灵图样式 */
.tile-sprite {
    /* 精灵图参数：图片617x373，需要精确测量每张牌位置 */
    /* 每张牌显示尺寸（适当缩小以完整显示边框） */
    --tile-display-width: 57px;
    --tile-display-height: 85px;
    --scale: 0.65;
    width: calc(var(--tile-display-width) * var(--scale));
    height: calc(var(--tile-display-height) * var(--scale));
    background-image: url('麻将大图.jpg');
    /* 背景图缩放到617x373的0.65倍 */
    background-size: calc(617px * var(--scale)) calc(373px * var(--scale));
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.1s ease;
    position: relative;
    box-shadow:
        1px 0 0 #c8c0b8,
        0 2px 0 #d0c8c0,
        0 3px 0 #c0b8b0,
        0 4px 0 #b0a8a0,
        0 5px 3px rgba(0,0,0,0.3);
    border: 1px solid #d8d0c8;
    flex-shrink: 0;
}

.tile-sprite:hover {
    transform: translateY(-5px);
    box-shadow:
        1px 0 0 #c8c0b8,
        0 3px 0 #d0c8c0,
        0 5px 0 #c0b8b0,
        0 7px 0 #b0a8a0,
        0 9px 6px rgba(0,0,0,0.35);
    z-index: 10;
}

.tile-sprite.selected {
    transform: translateY(-12px);
    box-shadow:
        1px 0 0 #c8c0b8,
        0 4px 0 #d0c8c0,
        0 7px 0 #c0b8b0,
        0 10px 0 #b0a8a0,
        0 13px 10px rgba(0,0,0,0.4);
    z-index: 20;
}

/* 万能牌样式 - 癞子 */
.tile-sprite.wild {
    border: 2px solid #ffa000;
    box-shadow:
