/* 手牌区域包装器 */
.hand-area-wrapper {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
}

/* 手牌提示区 */
.hand-hint {
    position: absolute;
    top: -90px;
    right: 10px;
    display: flex;
    align-items: center;
    gap: 10px;
    background: linear-gradient(180deg, #2a5a3a 0%, #1a472a 100%);
