    --tile-display-width: 57px;
    --tile-display-height: 85px;
    --scale: 0.65;
    width: calc(var(--tile-display-width) * var(--scale));
    height: calc(var(--tile-display-height) * var(--scale));
    background-image: url('麻将大图.jpg');
